CREATE TABLE IF NOT EXISTS tipos_conta (id BIGSERIAL PRIMARY KEY, nome VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pessoas (id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, cpf VARCHAR(11) NOT NULL UNIQUE, email VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS contas_bancarias (id BIGSERIAL PRIMARY KEY, agencia VARCHAR(4) NOT NULL, numero VARCHAR(8) NOT NULL, saldo NUMERIC(19,2) NOT NULL CHECK (saldo >= 0), ativa BOOLEAN NOT NULL, titular_id BIGINT NOT NULL REFERENCES pessoas(id), tipo_conta_id BIGINT NOT NULL REFERENCES tipos_conta(id), CONSTRAINT uk_conta_agencia_numero UNIQUE (agencia, numero));
